import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import FilterSidebar from './FilterSidebar';
import ProductGrid from './ProductGrid';
import Header from '../../components/Header';
import Footer from '../../components/Footer';
import { initProducts } from '../../data/productsData';

function ProductsPage() {
    const [products, setProducts] = useState([]);
    const [filteredProducts, setFilteredProducts] = useState([]);
    
    // Filters state
    const [selectedCategories, setSelectedCategories] = useState([]);
    const [priceRange, setPriceRange] = useState(10000);
    const [inStockOnly, setInStockOnly] = useState(true);
    const [sortOption, setSortOption] = useState('Relevance');

    useEffect(() => {
        initProducts(true);
        const storedProducts = localStorage.getItem("products");
        if (storedProducts) {
            const parsed = JSON.parse(storedProducts);
            setProducts(parsed);
            setFilteredProducts(parsed);
        }
    }, []);

    useEffect(() => {
        let result = [...products];

        // Filter by category
        if (selectedCategories.length > 0) {
            result = result.filter(p => {
                return selectedCategories.some(cat => {
                    if (cat === 'Servers' && p.category.includes('Server')) return true;
                    if (cat === 'Workstations' && p.category.includes('Workstation')) return true;
                    if (cat === 'Storage' && p.category.includes('Storage')) return true;
                    if (cat === 'Laptops' && p.category.includes('Mobile')) return true;
                    if(cat==='Gaming' && p.category.includes('Gaming'))
                        return true;
                    if(cat==='Monitors' && p.category.includes('Monitor'))
                        return true;
                    return false;
                });
            });
        }

        // Filter by price
        result = result.filter(p => {
            const priceVal = parseFloat(p.price.replace(/[^0-9.-]+/g,""));
            return priceVal <= priceRange;
        });

        // Sort
        if (sortOption === 'Price: Low to High') {
            result.sort((a, b) => parseFloat(a.price.replace(/[^0-9.-]+/g,"")) - parseFloat(b.price.replace(/[^0-9.-]+/g,"")));
        } else if (sortOption === 'Price: High to Low') {
            result.sort((a, b) => parseFloat(b.price.replace(/[^0-9.-]+/g,"")) - parseFloat(a.price.replace(/[^0-9.-]+/g,"")));
        }

        setFilteredProducts(result);
    }, [products, selectedCategories, priceRange, inStockOnly, sortOption]);

    return (
        <>
            <Header />
            <main className="pt-24 pb-16 px-margin-desktop max-w-container-max mx-auto min-h-[80vh]">
                <nav className="mb-8 flex items-center gap-2 text-on-surface-variant font-label-md text-label-md">
                    <Link to="/home" className="hover:text-secondary transition-colors">Home</Link>
                    <span className="material-symbols-outlined text-[16px]">chevron_right</span>
                    <span className="text-primary font-bold">Products</span>
                </nav>
                <div className="flex flex-col lg:flex-row gap-gutter">
                    <FilterSidebar 
                        selectedCategories={selectedCategories} 
                        setSelectedCategories={setSelectedCategories}
                        priceRange={priceRange}
                        setPriceRange={setPriceRange}
                        inStockOnly={inStockOnly}
                        setInStockOnly={setInStockOnly}
                    />
                    <ProductGrid 
                        products={filteredProducts} 
                        sortOption={sortOption} 
                        setSortOption={setSortOption} 
                    />
                </div>
            </main>
            <Footer />
        </>
    );
}

export default ProductsPage;
